def apply_transformation_fixed(grid, rows, cols):
    output = [[0 for _ in range(cols)] for _ in range(rows)]

    val_counts = {}
    for r in range(rows):
        for c in range(cols):
            v = grid[r][c]
            if v != 0:
                val_counts[v] = val_counts.get(v, 0) + 1

    sorted_vals = sorted(val_counts.keys())

    # Get input bboxes
    val_bbox = {}
    for v in sorted_vals:
        cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == v]
        min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
        min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)
        height = max_r - min_r + 1
        width = max_c - min_c + 1
        val_bbox[v] = (height, width)  # as (h, w)

    for v in sorted_vals:
        bh, bw = val_bbox[v]
        print(f"Value {v}: input bbox {bh}x{bw}, count={val_counts[v]}")

    for v in sorted_vals:
        bh, bw = val_bbox[v]
        count = val_counts[v]

        # Start: v=1->(0,0), v>1 -> (v, v-1)
        start_row = 0 if v == 1 else v
        start_col = 0 if v == 1 else (v - 1)

        print(f"Value {v}: start=({start_row},{start_col}), {count} cells, orig={bh}x{bw}")

        if bh == 1:
            # Row shape -> becomes column
            # Demo v=4: 1x4 becomes 4x1, keep all 4 cells
            for i in range(min(count, rows - start_row)):
                output[start_row + i][start_col] = v
        elif bw == 1:
            # Column shape -> stays column
            # Demo v=2/v=3: 2x2 becomes 2x2 XX/X, lose 1 cell
            for i in range(count):
                r = start_row + i
                c = start_col
                if 0 <= r < rows:
                    output[r][c] = v
        else:
            # Sqaure (bx>1, bh>1) -> swapped bbox triangle
            # Demo v=1: 2x3 (6 cells input) -> 3x2 (5 cells: XX/XX/X)
            # Demo v=2/v=3: 2x2 (4 cells) -> 2x2 (3 cells: XX/X)
            # For 2x2 bbox: use XX/X pattern (3 cells)
            # For 2x3+ bbox: use XX/XX/X pattern (5 cells from 6)

            new_h, new_w = bw, bh  # swap

            # Create the triangle pattern
            cells_out = []
            if new_h >= 1 and new_w >= 1:
                # For 2x2 (w=2, h=2): cells (0,0), (0,1), (1,0) = 3 cells
                rmax = min(new_h - 1, count - 1)
                cmax = min(new_w - 1, count - new_h - 1) if count >= 3 else 0

                for i in range(min(count, new_h)):
                    for j in range(min(new_w)):
                        if i == j:  # Slice off diagonal? No...
                            pass
                        # Fill upper triangle
                        if j < new_w - 1 and i + j < new_h + new_w - 1:
                            cells_out.append((i, j))

            # Simpler: for w=2, h=2: fill XX/X
            # For w>=2, h=2: fill XX/XX/something
            if new_h == 2 and new_w >= 2:
                # 2 rows
                row0_cells = min(new_w, max(2, count - 1))
                row1_cells = min(new_w - 1, count - row0_cells)
                for j in range(row0_cells):
                    cells_out.append((0, j))
                for j in range(row1_cells):
                    cells_out.append((1, j))
            elif new_w == 2 and new_h >= 2:
                # 2 cols
                col0_cells = min(new_h, max(2, count - 1))
                col1_cells = min(new_h - 1, count - col0_cells)
                for i in range(col0_cells):
                    cells_out.append((i, 0))
                for i in range(col1_cells):
                    cells_out.append((i, 1))
            else:
                # Default: fill all in swapped bbox up to count, triangle-like
                for i in range(min(count, new_h)):
                    for j in range(min(new_w)):
                        cells_out.append((i, j))

            for (r, c) in cells_out:
                out_r = start_row + r
                out_c = start_col + c
                if 0 <= out_r < rows and 0 <= out_c < cols:
                    output[out_r][out_c] = v

        placed = [(r, c) for r in range(rows) for c in range(cols) if output[r][c] == v]
        print(f"  Cells: {placed}, count placed={len(placed)}")

    return output

