# Fixed version with proper if/elif structure
def apply_transformation_v5(grid, rows, cols):
    output = [[0 for _ in range(cols)] for _ in range(rows)]
    sorted_vals = sorted(set(x for r in grid for x in r if x != 0))

    for v in sorted_vals:
        cells = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == v]
        count = len(cells)
        min_r, max_r = min(c[0] for c in cells), max(c[0] for c in cells)
        min_c, max_c = min(c[1] for c in cells), max(c[1] for c in cells)
        bh, bw = max_r - min_r + 1, max_c - min_c + 1

        start_row = 0 if v == 1 else v
        start_col = 0 if v == 1 else v - 1

        placed = 0

        # Case 1: Row input (ha 1, width>1) becomes column
        if bh == 1 and bw > 1:
            for i in range(min(count, rows - start_row)):
                out_r, out_c = start_row + i, start_col
                if out_r < rows and out_c < cols:
                    output[out_r][out_c] = v

        # Case 2: Column input (any height, width=1) stays column
        elif bw == 1:
            for i in range(min(count, rows - start_row)):
                out_r, out_c = start_row + i, start_col
                if out_r < rows and out_c < cols:
                    output[out_r][out_c] = v

        # Case 3: Square-ish (both dims >=2) becomes triangle (skip 1 corner)
        else:
            for r in range(min(bh, rows - start_row)):
                for c in range(min(bw, cols - start_col)):
                    # Skip the bottom-right corner for triangle effect
                    if r == bh - 1 and c == bw - 1:
                        continue
                    out_r = start_row + r
                    out_c = start_col + c
                    if out_r < rows and out_c < cols:
                        output[out_r][out_c] = v

        placed_cells = [(r, c) for r in range(rows) for c in range(cols) if output[r][c] == v]
        print(f"Value {v}: bh={bh} bw={bw} count={count} -> {len(placed_cells)} places: {placed_cells}")

    return output

